//! LuaJIT 2.1 bytecode instructions: the stock opcodes (`src/lj_bc.h` of
//! the pinned LuaJIT, `BCDEF`), their encoding and their operand modes.
//!
//! An instruction is 32 bits: `op` in the low byte, `A` in the next, and
//! either a 16-bit `D` or the pair `C` (bits 16–23), `B` (bits 24–31).
//! Jumps store `target - (pc + 1) + BCBIAS_J` in `D`.
//!
//! The function headers (`FUNCF`…) are regenerated by the loader and never
//! written to a dump, and the `I`/`J` variants are produced by the VM at
//! run time. The bit operators (`BNOT`…`BSAR`, register operands only)
//! sit between `JMP` and `FUNCF`: LuaJIT 2.1 took them from 3.0, with
//! the semantics of the `bit` library on numbers. A dump that uses them
//! carries `BCDUMP_F_BITOP`; its prototypes do not carry `PROTO_BITOP`
//! (see [`crate::proto`]). NL emits them only at feature level 1, for
//! operands proven numbers: a level-0 dump keeps to the
//! opcodes of the LuaJIT 2.1 releases before them, which other hosts
//! still run.
//!
//! The fork's opcodes (`BCDEF_NL` in
//! `src/lj_bc.h`) come right before the function headers, so the stock
//! numbering is unchanged: `CMPGT`/`CMPNGT` and `CMPGE`/`CMPNGE` are `>`
//! and `>=` under NL's rules and their negations (`op ^ 1`, as `ISLT` and
//! `ISGE`); `KINTR` loads a runtime intrinsic by index; `ISMETH` tests
//! whether a member is called as a method; `MSELF` keeps or drops the
//! receiver before a `CALLM`. A dump that uses any of them carries
//! `BCDUMP_F_NL` and is emitted only at feature level 1.

/// An instruction.
pub type Ins = u32;

/// The jump bias of operand `D`.
pub const BCBIAS_J: u32 = 0x8000;
/// The largest `A`, `B` or `C`.
pub const BCMAX_ABC: u32 = 0xff;
/// The largest `D`.
pub const BCMAX_D: u32 = 0xffff;
/// "No register" in `A` of a test instruction (`ISTC`/`ISFC`).
pub const NO_REG: u32 = BCMAX_ABC;
/// The empty jump list.
pub const NO_JMP: u32 = u32::MAX;

/// The slots a function may use (`LJ_MAX_SLOTS`).
pub const MAX_SLOTS: u32 = 250;
/// Local variables per function (`LJ_MAX_LOCVAR`).
pub const MAX_LOCVAR: u32 = 200;
/// Upvalues per function (`LJ_MAX_UPVAL`).
pub const MAX_UPVAL: u32 = 60;
/// Instructions per function (`LJ_MAX_BCINS`).
pub const MAX_BCINS: u32 = 1 << 26;

/// The stock opcodes, numbered as in `BCDEF`.
#[allow(missing_docs, clippy::upper_case_acronyms)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(u8)]
#[rustfmt::skip]
pub enum Op {
    ISLT = 0, ISGE, ISLE, ISGT,
    ISEQV, ISNEV, ISEQS, ISNES, ISEQN, ISNEN, ISEQP, ISNEP,
    ISTC, ISFC, IST, ISF, ISTYPE, ISNUM,
    MOV, NOT, UNM, LEN,
    ADDVN, SUBVN, MULVN, DIVVN, MODVN,
    ADDNV, SUBNV, MULNV, DIVNV, MODNV,
    ADDVV, SUBVV, MULVV, DIVVV, MODVV,
    POW, CAT,
    KSTR, KCDATA, KSHORT, KNUM, KPRI, KNIL,
    UGET, USETV, USETS, USETN, USETP, UCLO, FNEW,
    TNEW, TDUP, GGET, GSET, TGETV, TGETS, TGETB, TGETR, TSETV, TSETS, TSETB, TSETM, TSETR,
    CALLM, CALL, CALLMT, CALLT, ITERC, ITERN, VARG, ISNEXT,
    RETM, RET, RET0, RET1,
    FORI, JFORI, FORL, IFORL, JFORL,
    ITERL, IITERL, JITERL,
    LOOP, ILOOP, JLOOP,
    JMP,
    BNOT, BAND, BOR, BXOR, BSHL, BSHR, BSAR,
    CMPGT, CMPNGT, CMPGE, CMPNGE, KINTR, ISMETH, MSELF,
    FUNCF, IFUNCF, JFUNCF, FUNCV, IFUNCV, JFUNCV, FUNCC, FUNCCW,
}

#[rustfmt::skip]
const ALL_OPS: [Op; 111] = {
    use Op::*;
    [
        ISLT, ISGE, ISLE, ISGT, ISEQV, ISNEV, ISEQS, ISNES, ISEQN, ISNEN, ISEQP, ISNEP, ISTC, ISFC, IST, ISF, ISTYPE,
        ISNUM, MOV, NOT, UNM, LEN, ADDVN, SUBVN, MULVN, DIVVN, MODVN, ADDNV, SUBNV, MULNV, DIVNV, MODNV, ADDVV, SUBVV,
        MULVV, DIVVV, MODVV, POW, CAT, KSTR, KCDATA, KSHORT, KNUM, KPRI, KNIL, UGET, USETV, USETS, USETN, USETP, UCLO,
        FNEW, TNEW, TDUP, GGET, GSET, TGETV, TGETS, TGETB, TGETR, TSETV, TSETS, TSETB, TSETM, TSETR, CALLM, CALL,
        CALLMT, CALLT, ITERC, ITERN, VARG, ISNEXT, RETM, RET, RET0, RET1, FORI, JFORI, FORL, IFORL, JFORL, ITERL,
        IITERL, JITERL, LOOP, ILOOP, JLOOP, JMP, BNOT, BAND, BOR, BXOR, BSHL, BSHR, BSAR, CMPGT, CMPNGT, CMPGE, CMPNGE,
        KINTR, ISMETH, MSELF, FUNCF, IFUNCF, JFUNCF, FUNCV, IFUNCV, JFUNCV, FUNCC, FUNCCW,
    ]
};

/// What an operand holds (the columns of `BCDEF`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mode {
    /// Unused.
    None,
    /// A slot that is read.
    Var,
    /// A slot that is written.
    Dst,
    /// The base of a range of slots.
    Base,
    /// A slot or base used as a hint (`JMP`, `LOOP`, `UCLO`, `RET`).
    RBase,
    /// An upvalue index.
    Uv,
    /// A literal.
    Lit,
    /// A signed literal (`KSHORT`).
    Lits,
    /// A primitive: 0 nil, 1 false, 2 true.
    Pri,
    /// A number constant index.
    Num,
    /// A string constant index.
    Str,
    /// A template table constant index.
    Tab,
    /// A child prototype index.
    Func,
    /// A cdata constant (never emitted).
    Cdata,
    /// A jump offset.
    Jump,
}

/// The operand modes of an opcode: `(A, B, C or D)`. `B` is `None` for
/// the `AD` layout.
pub fn modes(op: Op) -> (Mode, Mode, Mode) {
    use Mode::*;
    use Op::*;
    match op {
        ISLT | ISGE | ISLE | ISGT | ISEQV | ISNEV => (Var, None, Var),
        ISEQS | ISNES => (Var, None, Str),
        ISEQN | ISNEN => (Var, None, Num),
        ISEQP | ISNEP => (Var, None, Pri),
        ISTC | ISFC => (Dst, None, Var),
        IST | ISF => (None, None, Var),
        ISTYPE | ISNUM => (Var, None, Lit),
        MOV | NOT | UNM | LEN => (Dst, None, Var),
        ADDVN | SUBVN | MULVN | DIVVN | MODVN => (Dst, Var, Num),
        ADDNV | SUBNV | MULNV | DIVNV | MODNV => (Dst, Var, Num),
        ADDVV | SUBVV | MULVV | DIVVV | MODVV | POW => (Dst, Var, Var),
        CAT => (Dst, RBase, RBase),
        KSTR => (Dst, None, Str),
        KCDATA => (Dst, None, Cdata),
        KSHORT => (Dst, None, Lits),
        KNUM => (Dst, None, Num),
        KPRI => (Dst, None, Pri),
        KNIL => (Base, None, Base),
        UGET => (Dst, None, Uv),
        USETV => (Uv, None, Var),
        USETS => (Uv, None, Str),
        USETN => (Uv, None, Num),
        USETP => (Uv, None, Pri),
        UCLO => (RBase, None, Jump),
        FNEW => (Dst, None, Func),
        TNEW => (Dst, None, Lit),
        TDUP => (Dst, None, Tab),
        GGET => (Dst, None, Str),
        GSET => (Var, None, Str),
        TGETV | TGETR => (Dst, Var, Var),
        TGETS => (Dst, Var, Str),
        TGETB => (Dst, Var, Lit),
        TSETV | TSETR => (Var, Var, Var),
        TSETS => (Var, Var, Str),
        TSETB => (Var, Var, Lit),
        TSETM => (Base, None, Num),
        CALLM | CALL | ITERC | ITERN | VARG => (Base, Lit, Lit),
        CALLMT | CALLT => (Base, None, Lit),
        ISNEXT => (Base, None, Jump),
        RETM => (Base, None, Lit),
        RET | RET0 | RET1 => (RBase, None, Lit),
        FORI | JFORI | FORL | IFORL | ITERL | IITERL => (Base, None, Jump),
        JFORL | JITERL => (Base, None, Lit),
        LOOP | ILOOP | JMP => (RBase, None, Jump),
        JLOOP => (RBase, None, Lit),
        BNOT => (Dst, None, Var),
        BAND | BOR | BXOR | BSHL | BSHR | BSAR => (Dst, Var, Var),
        CMPGT | CMPNGT | CMPGE | CMPNGE | ISMETH => (Var, None, Var),
        KINTR => (Dst, None, Lit),
        MSELF => (RBase, Lit, Lit),
        FUNCF | IFUNCF | FUNCV | IFUNCV | FUNCC | FUNCCW => (RBase, None, None),
        JFUNCF | JFUNCV => (RBase, None, Lit),
    }
}

impl Op {
    /// The opcode of an instruction, if it is a known one.
    pub fn from_ins(ins: Ins) -> Option<Op> {
        Op::from_u8((ins & 0xff) as u8)
    }

    /// The opcode with this number.
    pub fn from_u8(n: u8) -> Option<Op> {
        ALL_OPS.get(n as usize).copied()
    }

    /// True for the opcodes that end a function's control flow: returns
    /// and tail calls.
    pub fn is_ret_or_tail(self) -> bool {
        matches!(self, Op::RETM | Op::RET | Op::RET0 | Op::RET1 | Op::CALLMT | Op::CALLT)
    }

    /// True for the fork's opcodes (feature level 1).
    pub fn is_nl(self) -> bool {
        matches!(self, Op::CMPGT | Op::CMPNGT | Op::CMPGE | Op::CMPNGE | Op::KINTR | Op::ISMETH | Op::MSELF)
    }

    /// True for the bit operators (`PROTO_BITOP`), which NL emits at
    /// feature level 1 only.
    pub fn is_bitop(self) -> bool {
        matches!(self, Op::BNOT | Op::BAND | Op::BOR | Op::BXOR | Op::BSHL | Op::BSHR | Op::BSAR)
    }

    /// True for an opcode the emitter may write to a dump (no function
    /// header, no `I`/`J` variant, no cdata).
    pub fn is_emittable(self) -> bool {
        use Op::*;
        !matches!(
            self,
            KCDATA
                | JFORI
                | IFORL
                | JFORL
                | IITERL
                | JITERL
                | ILOOP
                | JLOOP
                | FUNCF
                | IFUNCF
                | JFUNCF
                | FUNCV
                | IFUNCV
                | JFUNCV
                | FUNCC
                | FUNCCW
        )
    }
}

/// `op A, B, C`.
pub fn abc(op: Op, a: u32, b: u32, c: u32) -> Ins {
    (op as u32) | ((a & 0xff) << 8) | ((c & 0xff) << 16) | ((b & 0xff) << 24)
}

/// `op A, D`.
pub fn ad(op: Op, a: u32, d: u32) -> Ins {
    (op as u32) | ((a & 0xff) << 8) | ((d & 0xffff) << 16)
}

/// `op A, J` with a jump offset (`NO_JMP` for an unpatched jump).
pub fn aj(op: Op, a: u32, j: u32) -> Ins {
    ad(op, a, j.wrapping_add(BCBIAS_J))
}

/// The opcode byte.
pub fn op_of(ins: Ins) -> u8 {
    (ins & 0xff) as u8
}
/// Operand `A`.
pub fn a_of(ins: Ins) -> u32 {
    (ins >> 8) & 0xff
}
/// Operand `B`.
pub fn b_of(ins: Ins) -> u32 {
    ins >> 24
}
/// Operand `C`.
pub fn c_of(ins: Ins) -> u32 {
    (ins >> 16) & 0xff
}
/// Operand `D`.
pub fn d_of(ins: Ins) -> u32 {
    ins >> 16
}
/// The jump offset of a jump instruction, relative to `pc + 1`.
pub fn j_of(ins: Ins) -> i32 {
    d_of(ins) as i32 - BCBIAS_J as i32
}

pub fn set_op(ins: &mut Ins, op: Op) {
    *ins = (*ins & !0xff) | op as u32;
}
pub fn set_a(ins: &mut Ins, a: u32) {
    *ins = (*ins & !0xff00) | ((a & 0xff) << 8);
}
pub fn set_b(ins: &mut Ins, b: u32) {
    *ins = (*ins & 0x00ff_ffff) | ((b & 0xff) << 24);
}
pub fn set_c(ins: &mut Ins, c: u32) {
    *ins = (*ins & !0x00ff_0000) | ((c & 0xff) << 16);
}
pub fn set_d(ins: &mut Ins, d: u32) {
    *ins = (*ins & 0xffff) | ((d & 0xffff) << 16);
}
pub fn set_j(ins: &mut Ins, j: u32) {
    set_d(ins, j.wrapping_add(BCBIAS_J));
}

/// The primitive operands of `KPRI`/`ISEQP`/`USETP` (`~itype`).
pub const PRI_NIL: u32 = 0;
pub const PRI_FALSE: u32 = 1;
pub const PRI_TRUE: u32 = 2;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn numbering_matches_bcdef() {
        assert_eq!(Op::ISLT as u8, 0);
        assert_eq!(Op::ISTYPE as u8, 16);
        assert_eq!(Op::KSTR as u8, 39);
        assert_eq!(Op::CALLM as u8, 65);
        assert_eq!(Op::JMP as u8, 88);
        assert_eq!(Op::BNOT as u8, 89);
        assert_eq!(Op::BAND as u8, 90);
        assert_eq!(Op::BSAR as u8, 95);
        assert_eq!(Op::CMPGT as u8, 96);
        assert_eq!(Op::CMPGT as u8 ^ 1, Op::CMPNGT as u8);
        assert_eq!(Op::CMPGE as u8 ^ 1, Op::CMPNGE as u8);
        assert_eq!(Op::MSELF as u8, 102);
        assert_eq!(Op::FUNCF as u8, 103);
        assert_eq!(Op::FUNCCW as u8, 110);
        for n in 0..=110u8 {
            assert_eq!(Op::from_u8(n).map(|o| o as u8), Some(n));
        }
        assert!(Op::from_u8(111).is_none());
    }

    #[test]
    fn encoding() {
        let i = abc(Op::ADDVV, 1, 2, 3);
        assert_eq!((op_of(i), a_of(i), b_of(i), c_of(i)), (Op::ADDVV as u8, 1, 2, 3));
        let j = aj(Op::JMP, 5, NO_JMP);
        assert_eq!(j_of(j), -1);
        let mut k = ad(Op::KSHORT, 0, 0xffff);
        set_d(&mut k, 7);
        assert_eq!(d_of(k), 7);
        set_a(&mut k, 9);
        assert_eq!((a_of(k), d_of(k)), (9, 7));
    }
}
